import{_ as a,C as l,o as s,c as n,j as t,a as o,E as i,a2 as d}from"./chunks/framework.DBmpDOAE.js";const y=JSON.parse('{"title":"5. Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/changelog.md","filePath":"gdd/changelog.md"}'),h={name:"gdd/changelog.md"},g={id:"latest-main",tabindex:"-1"};function p(u,e,c,f,m,b){const r=l("Badge");return s(),n("div",null,[e[3]||(e[3]=t("h1",{id:"_5-changelog",tabindex:"-1"},[o("5. Changelog "),t("a",{class:"header-anchor",href:"#_5-changelog","aria-label":'Permalink to "5. Changelog"'},"​")],-1)),e[4]||(e[4]=t("p",null,[o("Every published version stays playable at its own URL. The "),t("a",{href:"https://taigd98.github.io/dot-line/",target:"_blank",rel:"noreferrer"},"landing page"),o(" lists them all.")],-1)),t("h2",g,[e[0]||(e[0]=o("latest (main) ",-1)),i(r,{type:"tip",text:"Live"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#latest-main","aria-label":'Permalink to "latest (main) <Badge type="tip" text="Live" />"'},"​",-1))]),e[5]||(e[5]=d('<ul><li>No changes since v0.6.0.</li></ul><p><a href="https://taigd98.github.io/dot-line/demo/" target="_blank" rel="noreferrer">Play latest</a></p><h2 id="v0-6-0" tabindex="-1">v0.6.0 <a class="header-anchor" href="#v0-6-0" aria-label="Permalink to &quot;v0.6.0&quot;">​</a></h2><ul><li><strong>Colours per theme:</strong> each theme has its own list of colours shown as they are (17 on the light board, 19 on the dark board, picked by eye). Any other colour is shown as a kept colour that does not clash with the lines crossing or near it; it no longer has to be of the same hue family.</li><li><strong>Fluffy theme</strong> at <a href="https://taigd98.github.io/dot-line/fluffy/" target="_blank" rel="noreferrer">/fluffy/</a> (<strong>Play Fluffy</strong> on the landing page): every dot is a fluffy ball with a face. Asleep it breathes; tapped it sheds a puff of fur (a tap on empty board throws out tiny faint fluffy balls that fall away); running it looks surprised and leaves a long trail with sparkles; bumped it squeezes its eyes shut (<code>&gt; &lt;</code>) and loses tufts of fur; meeting its partner they bump in a puff of fur, happy (<code>^ ^</code>), stay together a moment (0.2 s), then pop into little hearts. Fur is always the ball&#39;s own colour. The board is a pattern of fluffy faces that scrolls diagonally and zooms with the level. The hearts take the colour of the pair; the fur is matte, with clearly visible strands, and each ball is lit from the top left so it reads round.</li></ul><p><a href="https://taigd98.github.io/dot-line/v0.6.0/demo/" target="_blank" rel="noreferrer">Play v0.6.0</a> · <a href="https://taigd98.github.io/dot-line/v0.6.0/docs/" target="_blank" rel="noreferrer">Docs v0.6.0</a> · <a href="https://taigd98.github.io/dot-line/v0.6.0/fluffy/" target="_blank" rel="noreferrer">Play Fluffy v0.6.0</a></p><h2 id="v0-5-0" tabindex="-1">v0.5.0 <a class="header-anchor" href="#v0-5-0" aria-label="Permalink to &quot;v0.5.0&quot;">​</a></h2><p><strong>Three ways to play</strong> (landing page: <strong>Play Classic</strong>, <strong>Play Jelly</strong>, <strong>Play Magic</strong>; the same levels in each)</p><ul><li><strong>Jelly</strong> (<a href="https://taigd98.github.io/dot-line/jelly/" target="_blank" rel="noreferrer">/jelly/</a>): dots deform while they move instead of leaving a trail, jiggle more on a bump, and a dot that reaches its partner presses into it and merges into one blob before popping.</li><li><strong>Magic</strong> (<a href="https://taigd98.github.io/dot-line/magic/" target="_blank" rel="noreferrer">/magic/</a>): the level is a seal on a double door in the board colours. The leaves slam shut, one dot of each pair runs along its line to the other end, then play starts (a tutorial caption only shows from then on). When the last dot is gone the level&#39;s map (lines and dots) glows gold, the seam lights up and the door opens, each leaf taking its half of the map, onto a glowing room behind it; the HUD bands slide away for the Well Done screen and back in on the next level. Glass orb dots in every colour.</li></ul><p><strong>Feel</strong></p><ul><li><strong>Droplets:</strong> when two dots bump, each splashes a few droplets in its own colour; a dot reaching its partner splashes too before the pair pops (every version).</li><li><strong>Smaller hitbox:</strong> two dots bump when their centres are closer than 78% of their radii (was 85%). A dot a few px clear of a line (centre 25 px or more from it) no longer stops a dot running on that line; dots that do block a line now sit plainly on it.</li></ul><p><strong>Colours</strong></p><ul><li><strong>No two look-alike colours side by side:</strong> the 28 colours form 10 families (reds, oranges, yellows, limes, greens, cyans, blues, purples, magenta, pinks). Lines within 60 px of each other never share a colour or a family and always look clearly different, on the light and on the dark board alike. A level uses as many colours as it can.</li><li><strong>No line edges; colours that would sink into the board are swapped</strong> for a readable colour of the same family (light ones on the light board, deep ones on the dark board), and swapped back when the theme changes.</li></ul><p><strong>Levels</strong></p><ul><li><strong>All 30 levels generated again</strong> (chapter 6, same order, same tutorials) with the new colour rule, dots plainly on or off lines, and big dots on circles drawn as lines (the Christmas tree&#39;s ornaments). Small ghosts and other not-quite-round shapes stay lines.</li><li><strong>Fix:</strong> LEVEL 6 (Christmas tree) is no longer upside down.</li></ul><p><strong>Level editor</strong></p><ul><li><strong>Big dots from drawn circles:</strong> a line that curls round a circle, a loop or an open hook at the end of a line, and a round arc hanging from another line become big dots; lines pulled back to make room grow back where there is room again, so less of the drawing is lost.</li><li><strong>Saving no longer reloads the editor page</strong> (only the dev game reloads with the new levels).</li></ul><p><a href="https://taigd98.github.io/dot-line/v0.5.0/demo/" target="_blank" rel="noreferrer">Play v0.5.0</a> · <a href="https://taigd98.github.io/dot-line/v0.5.0/docs/" target="_blank" rel="noreferrer">Docs v0.5.0</a></p><h2 id="v0-4-0" tabindex="-1">v0.4.0 <a class="header-anchor" href="#v0-4-0" aria-label="Permalink to &quot;v0.4.0&quot;">​</a></h2><ul><li><strong>Play on:</strong> the &quot;Out of Hearts!&quot; screen has PLAY ON (AD): the hearts are refilled and the level goes on from where it stopped. QUIT asks &quot;Are you sure?&quot; first, showing the level&#39;s progress and that it will be lost: PLAY ON or REPLAY (start the level again).</li><li><strong>No more slow-motion ending:</strong> the last dot runs at normal speed and the end screen comes half a second after the pop.</li><li><strong>The game build contains exactly the play order</strong> (levels/game.json): only those levels, in that order (the game bundle shrank from ~3.9 MB to ~1 MB).</li><li><strong>Organiser:</strong> a <strong>Game · play order</strong> list (levels from any chapter, saved in <code>levels/game.json</code>, which the game now reads), a picture of every level in the lists, and a <strong>Tutorial</strong> choice per level.</li><li><strong>Level editor:</strong> a level-wide <strong>Dot size</strong> in the Inspector (every normal dot, cross lines included; big dots keep theirs) and a <strong>big dot</strong> box per dot (a pair can have one big and one normal dot). Big dots are sized from the drawing&#39;s detail, at least 1.3× the dot size. Small clusters of thick strokes (a nose with an &quot;x&quot; mouth) are no longer taken for a filled round detail.</li><li><strong>New level order:</strong> chapter 5&#39;s levels 25–28 now come right after the two tutorials (LEVEL 3–6); the pinch-to-zoom tutorial moved with them to LEVEL 3. Pumpkin (now LEVEL 7) was reworked by hand (17 lines).</li></ul><p><a href="https://taigd98.github.io/dot-line/v0.4.0/demo/" target="_blank" rel="noreferrer">Play v0.4.0</a> · <a href="https://taigd98.github.io/dot-line/v0.4.0/docs/" target="_blank" rel="noreferrer">Docs v0.4.0</a></p><h2 id="v0-3-0" tabindex="-1">v0.3.0 <a class="header-anchor" href="#v0-3-0" aria-label="Permalink to &quot;v0.3.0&quot;">​</a></h2><p><strong>Levels and tutorials</strong></p><ul><li><strong>Play order:</strong> level 1–2 of chapter 1 (tutorials: tap, bumping), then the 28 levels of chapter 5, drawn from public-domain line art (30 levels). Set in <code>src/game/playlist.ts</code>.</li><li><strong>Tutorials:</strong> level 2 forgives the first bump (&quot;Free this time! Next bump costs a heart&quot;); level 3 (Pumpkin) teaches pinch to zoom.</li><li><strong>Pumpkin (level 3)</strong> reworked by hand: one line fewer, still solvable.</li></ul><p><strong>Boosters</strong></p><ul><li>A bottom panel (in the board colour, over the board) holds the boosters: <strong>Hint</strong> (moved from the top right) and the new <strong>Cut</strong>: arm the scissors, then tap a line or dot to remove that pair.</li></ul><p><strong>Look and feel</strong></p><ul><li><strong>New colours:</strong> dots and lines use the 28 colours of the Voxel materials, with their shading ramps for the dots&#39; rim and gloss; no white or grey. Each level is coloured with one colour scheme (complementary, split-complementary or triadic), as many of its colours as possible, near lines never in the same colour.</li><li><strong>New board colours</strong> for the light and dark themes (Settings → THEME, remembered in the browser); lines that would sink into the board get a thin edge in their own tone.</li><li><strong>Glossy dots</strong> with soft drop shadows, <strong>striped dots</strong> after a bump (their next bumps are free), dots that stretch along their path with a fading trail, and an elastic wobble on bumps instead of a screen shake.</li><li><strong>Accelerating dots:</strong> a tapped dot starts at 500 px/s and gains 250 px/s every second; bumped dots return at 1020 px/s.</li><li><strong>Cleared lines disappear</strong> with their dots; the Well Done screen shows an empty board.</li><li><strong>Panning at any zoom</strong>, including the smallest (no more stuck off-centre board).</li></ul><p><strong>Level editor</strong></p><ul><li><strong>Chapters:</strong> each folder under <code>levels/</code> is a chapter with its own levels, history and collections.</li><li><strong>Generate from a drawing, stroke mode:</strong> each stroke of the drawing becomes one line, ends land on other strokes; smooth rounded lines with no kinks; one dot size per level (<strong>Dot size</strong>) and <strong>big dots</strong> on small round details; runs in the background so the editor never freezes. Part 2 adds an <strong>overlap pattern</strong> of X and T cross lines.</li><li><strong>Opening a local folder</strong> from the web editor works with the project folder or its <code>levels</code> folder, and errors are shown instead of silently doing nothing.</li></ul><p><a href="https://taigd98.github.io/dot-line/v0.3.0/demo/" target="_blank" rel="noreferrer">Play v0.3.0</a> · <a href="https://taigd98.github.io/dot-line/v0.3.0/docs/" target="_blank" rel="noreferrer">Docs v0.3.0</a></p><h2 id="v0-2-0" tabindex="-1">v0.2.0 <a class="header-anchor" href="#v0-2-0" aria-label="Permalink to &quot;v0.2.0&quot;">​</a></h2><ul><li><strong>100 levels:</strong> played in blocks of 5 from level 2 (relax, normal, hard, normal, normal). Levels 4, 9 and 14 are a little harder than their block; from level 19 hard levels are really hard. Each level is a familiar picture (rainbow, ladder, wheel, bookshelf, spider web...), drawn as SVG in <code>art/levels/</code>.</li><li><strong>Tutorials:</strong> level 1 tap, level 2 bumping costs a heart, level 8 pinch to zoom. Hard levels show the &quot;Hard&quot; label.</li><li><strong>Big dots</strong> only as an accent or a blocker, at most one pair per level.</li><li><strong>Fix:</strong> dots that only touch at the edge no longer count as a bump (hitbox = 85% of the two radii), e.g. the top of the sailboat&#39;s left sail.</li><li><strong>Level editor:</strong> opens the game&#39;s own levels when you choose the project folder; generating with many pairs keeps the whole drawing (stuck pairs are joined instead of removed); a difficulty dial puts dots on crossing lines.</li><li><strong>Game Design Document:</strong> difficulty score (pairs, blocking depth, trap share, colours) and the level system, also in <code>design/level-system.xlsx</code>.</li><li>The 10 earlier intro levels now come after level 100.</li></ul><p><a href="https://taigd98.github.io/dot-line/v0.2.0/demo/" target="_blank" rel="noreferrer">Play v0.2.0</a> · <a href="https://taigd98.github.io/dot-line/v0.2.0/docs/" target="_blank" rel="noreferrer">Docs v0.2.0</a></p><h2 id="v0-1-0" tabindex="-1">v0.1.0 <a class="header-anchor" href="#v0-1-0" aria-label="Permalink to &quot;v0.1.0&quot;">​</a></h2><ul><li><strong>Core loop:</strong> tap a dot and it runs along its line to its partner; reaching it pops the pair (bigger dots, bigger splash) and the line stays in the Completed colour.</li><li><strong>Blocking and hearts:</strong> bumping into another pair&#39;s dot sends the dot back and costs a heart; 3 hearts, none left = level lost. Several dots can run at once.</li><li><strong>HUD:</strong> pause, hearts, hint (zooms to 1.5x and nudges a dot that can go, marked AD), progress bar, &quot;Hard&quot; label on difficulty 4+.</li><li><strong>Camera:</strong> pinch to zoom up to 3x and drag to pan; the HUD does not zoom.</li><li><strong>Win / lose screens:</strong> &quot;Well Done!&quot; with confetti and CONTINUE, &quot;Out of Hearts!&quot; with RETRY.</li><li><strong>10 intro levels:</strong> Ripples, Flag and Kite teach tapping, bumping and pinch zoom; then House, Fish, Sailboat, Umbrella, Rocket, Tree and Castle.</li><li><strong>Level editor</strong> at <code>/editor/</code>: draw and bend pairs with snapping, generate levels from a PNG or SVG drawing (always solvable, pick 1 of 3 layouts), level checks and solver, versions, collections, play test.</li><li><strong>Game Design Document:</strong> overview, core loop, rules, palette and roadmap. Level difficulty targets are still to be decided.</li></ul><p><a href="https://taigd98.github.io/dot-line/v0.1.0/demo/" target="_blank" rel="noreferrer">Play v0.1.0</a> · <a href="https://taigd98.github.io/dot-line/v0.1.0/docs/" target="_blank" rel="noreferrer">Docs v0.1.0</a></p><h2 id="document-history" tabindex="-1">Document history <a class="header-anchor" href="#document-history" aria-label="Permalink to &quot;Document history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>2026-11-16</td><td>GDD created</td></tr><tr><td>2026-11-16</td><td>Imported GDD v0.2 (overview, core loop, rules, roadmap)</td></tr><tr><td>2026-11-16</td><td>Dây ở lại với màu Completed; thêm bảng màu (3.7)</td></tr><tr><td>2026-11-17</td><td>Released v0.1.0</td></tr><tr><td>2026-11-17</td><td>Released v0.2.0</td></tr><tr><td>2026-11-19</td><td>Released v0.5.0</td></tr><tr><td>2026-11-18</td><td>Released v0.3.0</td></tr><tr><td>2026-11-20</td><td>Released v0.6.0</td></tr></tbody></table>',38))])}const w=a(h,[["render",p]]);export{y as __pageData,w as default};
